<script setup lang="ts">
import { computed, onBeforeUnmount, reactive, ref, watch } from 'vue'
import { ElDialog } from 'element-plus'
import AppSelect from '@/components/AppSelect.vue'
import AppFileDropzone from '@/components/AppFileDropzone.vue'
import { Library, Film, Image, Music2, AudioLines, Sticker, Mic2, UsersRound, Folder, FolderPlus, Upload, Search, Plus, X, Play, MoreHorizontal, Pencil, Copy, List, LayoutGrid, RefreshCw } from 'lucide-vue-next'
import { useAuthStore } from '@/features/auth/authStore'
import { mediaUrl } from '@/api'
import { tr } from '@/i18n'
import { notice } from '@/shared/notice'
import { appConfirm } from '@/shared/confirmDialog'
import { libraryApi } from './api'
import { catalogApi, type CatalogResource, type CatalogKind, type MediaKind, type CatalogCapabilities } from './catalog'
import type { ResourceFolder } from './types'
import CatalogVoiceUpload from './CatalogVoiceUpload.vue'
import CatalogApplyDialog from './CatalogApplyDialog.vue'
import './dialog.css'
const props=withDefaults(defineProps<{kind?:CatalogKind;initialKind?:CatalogKind|'all';initialSearch?:string;allowedKinds?:CatalogKind[];pick?:boolean;maxSelection?:number}>(),{maxSelection:100})
const emit=defineEmits<{choose:[items:CatalogResource[]];changeKind:[kind:CatalogKind|'all']}>()
const auth=useAuthStore(),editable=computed(()=>auth.enabled===false||['admin','creator','super'].includes(auth.role||''))
const kinds=computed(()=>([{id:'all',label:tr('全部资源'),icon:Library},{id:'video',label:tr('视频'),icon:Film},{id:'image',label:tr('图片'),icon:Image},{id:'bgm',label:'BGM',icon:Music2},{id:'sound',label:tr('音效'),icon:AudioLines},{id:'sticker',label:tr('贴纸'),icon:Sticker},{id:'voice',label:tr('参考音色'),icon:Mic2},{id:'character',label:tr('角色库'),icon:UsersRound}] as const).filter(item=>!props.allowedKinds||(item.id!=='all'&&props.allowedKinds.includes(item.id))))
const active=ref<CatalogKind|'all'>(props.kind||props.initialKind||props.allowedKinds?.[0]||'all'),folder=ref<number|undefined>(),source=ref('all'),search=ref(props.initialSearch||''),keyword=ref(props.initialSearch||''),sort=ref('recent'),gender=ref(''),country=ref(''),age=ref(''),occupation=ref('')
const items=ref<CatalogResource[]>([]),folders=ref<ResourceFolder[]>([]),capabilities=ref<CatalogCapabilities|null>(null),page=ref(1),pages=ref(1),total=ref(0),loading=ref(false),error=ref(''),busy=ref(false),selected=ref<CatalogResource|null>(null),checked=ref<CatalogResource[]>([]),listView=ref(false)
const dialog=ref<'upload'|'folder'|'rename'|'move'|null>(null),folderName=ref(''),folderParent=ref(0),folderEditId=ref<number>(),renameValue=ref(''),moveFolder=ref(0),uploadKind=ref<MediaKind|'voice'>('video'),applyItem=ref<CatalogResource|null>(null),playing=ref<CatalogResource|null>(null),voiceForm=ref<InstanceType<typeof CatalogVoiceUpload>|null>(null)
const voiceValid=computed(()=>!!voiceForm.value?.valid),voiceBusy=computed(()=>!!voiceForm.value?.busy)
interface UploadJob {name:string;kind:MediaKind;folder:number;progress:number;state:'waiting'|'uploading'|'processing'|'done'|'failed';error:string;file:File;team:number|null}
const jobs=ref<UploadJob[]>([]),uploading=computed(()=>jobs.value.some(job=>['waiting','uploading','processing'].includes(job.state)))
let sequence=0,scope=0,disposed=false
const label=(kind:string)=>kinds.value.find(item=>item.id===kind)?.label||kind
const folderLabel=(id:number)=>{const row=folders.value.find(f=>f.id===id),parent=folders.value.find(f=>f.id===row?.parent_id);return row?(parent?`${parent.name} / ${row.name}`:row.name):tr('未分类')}
const heading=computed(()=>props.pick?tr('选择资源'):tr('资源库'))
const orderedFolders=computed(()=>folders.value.filter(f=>!f.parent_id).flatMap(f=>[f,...folders.value.filter(c=>c.parent_id===f.id)]))
const checkedKeys=computed(()=>checked.value.map(i=>i.key))
const canMove=computed(()=>editable.value&&checked.value.length>0&&checked.value.every(i=>i.editable))
const canDelete=computed(()=>editable.value&&checked.value.length>0&&checked.value.every(i=>i.deletable??(i.editable&&i.catalog==='media')))
const audioView=computed(()=>['bgm','sound','voice'].includes(active.value))
async function copyId(value:string){try{await navigator.clipboard.writeText(value);notice.success(tr('已复制资产 ID'))}catch{notice.error(tr('复制失败，请手动复制'))}}
function duration(n=0){return `${String(Math.floor(n/60)).padStart(2,'0')}:${String(Math.floor(n%60)).padStart(2,'0')}`}
function detail(item:CatalogResource){return item.kind==='character'?[item.country,item.gender,item.age?`${item.age} ${tr('岁')}`:'',item.occupation].filter(Boolean).join(' · '):item.kind==='voice'?[item.gender,item.asset_id].filter(Boolean).join(' · '):item.width?`${item.width}×${item.height}`:duration(item.duration)}
function originName(item:CatalogResource){return item.origin==='system'?tr('公共资源'):item.origin==='personal'?tr('个人历史资源'):tr('团队上传')}
async function load(next=1){const version=++sequence;page.value=next;loading.value=true;error.value='';try{const result=await catalogApi.list({kind:active.value,folder_id:folder.value,origin:source.value,search:keyword.value,page:next,sort:sort.value,gender:gender.value,country:country.value,age:age.value,occupation:occupation.value});if(version!==sequence||disposed)return;items.value=result.data.items;if(selected.value){selected.value=items.value.find(item=>item.key===selected.value?.key)||null;if(!selected.value)playing.value=null}total.value=result.data.pagination.total;pages.value=result.data.pagination.pages}catch(reason){if(version===sequence)error.value=reason instanceof Error?reason.message:tr('资源库加载失败')}finally{if(version===sequence)loading.value=false}}
async function initialize(){const version=++scope;++sequence;selected.value=null;checked.value=[];playing.value=null;items.value=[];total.value=0;pages.value=1;page.value=1;folders.value=[];capabilities.value=null;busy.value=false;dialog.value=null;applyItem.value=null;folder.value=undefined;jobs.value=[];error.value='';loading.value=true;try{const [caps,dirs]=await Promise.all([catalogApi.capabilities(),libraryApi.folders()]);if(version!==scope||disposed)return;capabilities.value=caps.data;folders.value=dirs.data;await load()}catch(reason){if(version===scope){loading.value=false;error.value=reason instanceof Error?reason.message:tr('资源库加载失败')}}}
watch(()=>auth.activeTeamId,initialize,{immediate:true})
watch(()=>props.kind,value=>{if(value&&value!==active.value)chooseKind(value)})
watch(()=>props.initialKind,value=>{if(value&&value!==active.value)chooseKind(value)})
watch([folder,source,sort,gender,country,age,occupation],()=>{selected.value=null;playing.value=null;void load()})
function chooseKind(kind:CatalogKind|'all'){active.value=kind;emit('changeKind',kind);folder.value=undefined;gender.value='';country.value='';age.value='';occupation.value='';source.value='all';search.value='';keyword.value='';selected.value=null;playing.value=null;checked.value=[];void load()}
function retryLoad(){if(capabilities.value)void load(page.value);else void initialize()}
function find(){keyword.value=search.value.trim();void load()}
function toggle(item:CatalogResource){if(item.state&&item.state!=='ready')return;if(checkedKeys.value.includes(item.key))checked.value=checked.value.filter(i=>i.key!==item.key);else if(checked.value.length<props.maxSelection)checked.value.push(item);else notice.info(tr('最多选择 {p0} 个资源',{p0:props.maxSelection}))}
function inspect(item:CatalogResource){selected.value=item;playing.value=null}
function preview(item:CatalogResource){selected.value=item;playing.value=playing.value?.key===item.key?null:item}
async function action(fn:()=>Promise<unknown>){if(busy.value||!editable.value)return;const version=scope;busy.value=true;error.value='';try{await fn();if(version===scope){dialog.value=null;const dirs=await libraryApi.folders();if(version!==scope||disposed)return;folders.value=dirs.data;await load()}}catch(reason){if(version===scope)error.value=reason instanceof Error?reason.message:tr('操作失败')}finally{if(version===scope)busy.value=false}}
function newFolder(row?:ResourceFolder){folderEditId.value=row?.id;folderName.value=row?.name||'';folderParent.value=row?.parent_id||0;dialog.value='folder'}
function saveFolder(){void action(()=>libraryApi.writeFolder(folderName.value,folderParent.value,folderEditId.value))}
function rename(){const item=selected.value,version=scope;if(item)void action(async()=>{const result=await catalogApi.rename(item.key,renameValue.value);if(version===scope&&selected.value?.key===item.key)selected.value=result.data})}
function move(){void action(async()=>{await catalogApi.move(checkedKeys.value,moveFolder.value);checked.value=[]})}
async function remove(){if(!canDelete.value)return;const keys=checkedKeys.value;if(!await appConfirm({title:tr('永久删除 {p0} 个资源？',{p0:keys.length}),message:tr(checked.value.some(item=>item.catalog==='media')?'将删除资源及其文件，已有项目引用可能失效。此操作不可恢复。':'将从资源库移除所选资源，已有引用可能失效。'),confirmLabel:tr('永久删除'),tone:'danger'}))return;void action(async()=>{const result=await catalogApi.delete(keys);if(result.data.some(row=>!row.deleted))throw new Error(tr('部分文件删除失败，请重试'));checked.value=[];selected.value=null})}
async function removeFolder(row:ResourceFolder){try{const result=(await libraryApi.deletePreview(row.id)).data;if(!await appConfirm({title:tr('永久删除文件夹“{p0}”？',{p0:row.name}),message:tr('包含 {p0} 个媒体资源。文件会被永久删除，引用可能失效；角色或参考音色须先移出。',{p0:result.resource_count}),confirmLabel:tr('永久删除'),tone:'danger'}))return;await action(async()=>{const result=await libraryApi.deleteFolder(row.id);if(result.data.some(i=>!i.deleted))throw new Error(tr('部分文件删除失败，请重试'))})}catch(reason){error.value=reason instanceof Error?reason.message:tr('操作失败')}}
function upload(){uploadKind.value=active.value==='all'||active.value==='character'?'video':active.value;dialog.value='upload'}
async function runJob(job:UploadJob){if(job.team!==auth.activeTeamId)return;const version=scope;job.error='';job.progress=0;job.state='uploading';try{await catalogApi.upload(job.file,job.kind,job.folder,n=>{if(version===scope){job.progress=n;job.state=n===100?'processing':'uploading'}});if(version===scope){job.progress=100;job.state='done';await load(page.value)}}catch(reason){if(version===scope){job.state='failed';job.error=reason instanceof Error?reason.message:tr('资源上传失败')}}}
async function acceptFiles(files:File[]){const kind=uploadKind.value;if(kind==='voice'||!files.length)return;const version=scope,batch=files.map(file=>reactive<UploadJob>({file,name:file.name,kind,folder:folder.value||0,progress:0,state:'waiting',error:'',team:auth.activeTeamId}));jobs.value.push(...batch);for(const job of batch){if(version!==scope)return;const limits=capabilities.value?.kinds[kind];if(!limits||job.file.size>limits.max_size_mb*1024*1024||!limits.formats.includes(job.file.name.split('.').pop()?.toLowerCase()||'')){job.state='failed';job.error=tr('文件格式或大小不符合当前资源类型');continue}await runJob(job)}}
function submitVoice(){void voiceForm.value?.upload()}
const accept=computed(()=>uploadKind.value==='voice'?'.mp3,.wav':capabilities.value?.kinds[uploadKind.value]?.formats.map(ext=>'.'+ext).join(',')||'')
onBeforeUnmount(()=>{disposed=true;++sequence;++scope})
defineExpose({refresh:load})
</script>
<template>
 <section class="resource-catalog" :class="{'is-picker':pick}">
  <header class="catalog-heading"><div><h1>{{heading}}</h1><p>{{tr('团队共享的创作素材，随时用于新的故事。')}}</p></div><div v-if="!pick" class="catalog-actions"><AppButton variant="secondary" size="sm" :disabled="!editable" @click="newFolder()"><FolderPlus :size="15"/>{{tr('新建文件夹')}}</AppButton><AppButton v-if="active!=='character'" variant="primary" size="sm" :disabled="!editable||!capabilities" @click="upload"><Upload :size="15"/>{{tr('上传资源')}}</AppButton></div></header>
  <nav v-if="!kind" class="catalog-tabs" :aria-label="tr('资源类型')"><button v-for="item in kinds" :key="item.id" :aria-pressed="active===item.id" @click="chooseKind(item.id)"><component :is="item.icon" :size="16"/>{{item.label}}</button></nav>
  <div class="catalog-body" :class="{inspecting:selected&&!pick}">
   <aside class="catalog-folders"><header><span>{{tr('文件夹')}}</span><button class="catalog-icon" :aria-label="tr('新建文件夹')" :disabled="!editable" @click="newFolder()"><Plus :size="14"/></button></header><button :class="{active:folder===undefined}" :aria-current="folder===undefined?'page':undefined" @click="folder=undefined"><Library :size="15"/>{{tr('全部文件夹')}}</button><button :class="{active:folder===0}" :aria-current="folder===0?'page':undefined" @click="folder=0"><Folder :size="15"/>{{tr('未分类')}}</button><div v-for="row in orderedFolders" :key="row.id" :class="['catalog-folder',{nested:row.parent_id,active:folder===row.id}]"><button :disabled="row.deleting" :aria-current="folder===row.id?'page':undefined" @click="folder=row.id"><Folder :size="15"/><span>{{row.name}}</span></button><details v-if="editable&&row.editable!==false"><summary :aria-label="tr('文件夹操作')"><MoreHorizontal :size="15"/></summary><div><button @click="newFolder(row)">{{tr('修改文件夹')}}</button><button @click="removeFolder(row)">{{tr('删除文件夹')}}</button></div></details></div><p>{{tr('移动素材不改变已有引用')}}</p></aside>
   <main class="catalog-content"><form class="catalog-filter" @submit.prevent="find"><label class="catalog-search"><Search :size="16"/><input v-model="search" :placeholder="tr('搜索资源')" :aria-label="tr('搜索资源')"/><button v-if="search" type="button" class="catalog-icon" :aria-label="tr('清除搜索')" @click="search='';find()"><X :size="14"/></button></label><AppSelect class="catalog-mobile-folder" :model-value="folder===undefined?'all':String(folder)" :options="[{value:'all',label:tr('全部文件夹')},{value:'0',label:tr('未分类')},...orderedFolders.map(row=>({value:String(row.id),label:folderLabel(row.id)}))]" :ariaLabel="tr('文件夹')" density="compact" @update:model-value="folder=$event==='all'?undefined:Number($event)" /><AppSelect v-model="source" :options="[{value:'all',label:tr('全部来源')},{value:'team',label:tr('团队上传')},{value:'system',label:tr('公共资源')},...((active==='voice'||active==='all')?[{value:'personal',label:tr('个人历史资源')}]:[])]" :ariaLabel="tr('资源来源')" density="compact" /><AppSelect v-model="sort" :options="[{value:'recent',label:tr('最近添加')},{value:'name',label:tr('名称顺序')}]" :ariaLabel="tr('排序')" density="compact" /><button type="button" class="catalog-icon" :aria-label="tr(listView?'切换网格':'切换列表')" @click="listView=!listView"><LayoutGrid v-if="listView" :size="17"/><List v-else :size="17"/></button></form>
    <div v-if="active==='character'||active==='voice'" class="catalog-special-filters"><AppSelect v-model="gender" :options="[{value:'',label:tr('全部性别')},{value:'male',label:tr('男')},{value:'female',label:tr('女')}]" :ariaLabel="tr('性别')" density="compact" /><template v-if="active==='character'"><input v-model.lazy="country" :aria-label="tr('国家或地区')" :placeholder="tr('国家或地区')"/><AppSelect v-model="age" :options="[{value:'',label:tr('全部年龄')},{value:'under-20',label:tr('20 岁以下')},...['20-29','30-39','40-59','60-plus'].map(value=>({value,label:value==='60-plus'?tr('60 岁以上'):value}))]" :ariaLabel="tr('年龄')" density="compact" /><input v-model.lazy="occupation" :aria-label="tr('职业')" :placeholder="tr('职业')"/></template></div>
    <div class="catalog-results"><span>{{folder===undefined?label(active):folderLabel(folder)}}<small>{{tr('{p0} 个资源',{p0:total})}}</small></span><div v-if="checked.length"><span>{{tr('已选 {p0} 个',{p0:checked.length})}}</span><button v-if="!pick" :disabled="!canMove" @click="dialog='move'">{{tr('移动到')}}</button><button v-if="!pick" :disabled="!canDelete" @click="remove">{{tr('删除')}}</button><button @click="checked=[]">{{tr('取消选择')}}</button></div></div>
    <div v-if="error" class="catalog-state" role="alert"><p>{{error}}</p><AppButton @click="retryLoad"><RefreshCw :size="15"/>{{tr('重新加载')}}</AppButton></div>
    <div v-else-if="loading" class="catalog-skeleton" role="status" :aria-label="tr('正在加载资源…')"><div v-for="n in 6" :key="n"/></div>
    <div v-else-if="!items.length" class="catalog-state"><Library :size="31"/><h3>{{tr('没有找到匹配的资源')}}</h3><p>{{tr('上传资源，或调整搜索和筛选条件。')}}</p><AppButton @click="search='';keyword='';gender='';country='';age='';occupation='';folder=undefined;source='all';load()">{{tr('重置筛选')}}</AppButton></div>
    <div v-else :class="audioView||listView?'catalog-list':'catalog-grid'">
     <article v-for="item in items" :key="item.key" :class="{selected:selected?.key===item.key}" @click="inspect(item)">
      <div class="catalog-cover" :class="['kind-'+item.kind,{'is-transparent':item.kind==='sticker'}]"><button class="catalog-preview" :aria-label="tr('预览 {p0}',{p0:item.name})" @click.stop="preview(item)"><img v-if="item.poster_url||(item.url&&['image','sticker','character'].includes(item.kind))" :src="mediaUrl(item.poster_url||item.url)" alt="" loading="lazy"/><component :is="kinds.find(k=>k.id===item.kind)?.icon||Film" v-else :size="audioView||listView?18:32"/><Play v-if="item.kind==='video'" class="catalog-play" :size="25"/></button><input type="checkbox" :aria-label="tr('选择 {p0}',{p0:item.name})" :checked="checkedKeys.includes(item.key)" :disabled="!!item.state&&item.state!=='ready'" @click.stop="toggle(item)"/><small v-if="item.duration&&!audioView&&!listView">{{duration(item.duration)}}</small></div>
      <div class="catalog-card-copy"><div><span>{{label(item.kind)}}</span><small>{{originName(item)}}</small></div><h3><button @click.stop="inspect(item)">{{item.name}}</button></h3><p>{{detail(item)}}</p><footer><span>{{item.origin==='system'?tr('公共资源'):folderLabel(item.folder_id)}}</span><button class="catalog-icon" :aria-label="tr('查看 {p0} 详情',{p0:item.name})" @click.stop="inspect(item)"><MoreHorizontal :size="16"/></button></footer><p v-if="item.state&&item.state!=='ready'" role="status">{{tr('删除处理中或失败，无法引用')}}</p></div><time v-if="audioView||listView">{{item.duration?duration(item.duration):'—'}}</time>
     </article>
    </div>
    <footer class="catalog-pagination"><AppButton size="sm" :disabled="page<=1||loading" @click="load(page-1)">{{tr('上一页')}}</AppButton><span>{{page}} / {{pages||1}}</span><AppButton size="sm" :disabled="page>=pages||loading" @click="load(page+1)">{{tr('下一页')}}</AppButton><AppButton v-if="pick" variant="primary" size="sm" :disabled="!checked.length" @click="emit('choose',checked)">{{tr('使用所选资源（{p0}）',{p0:checked.length})}}</AppButton></footer>
   </main>
   <aside v-if="selected&&!pick" class="catalog-details"><header><h2>{{tr('资源详情')}}</h2><button class="catalog-icon" :aria-label="tr('关闭详情')" @click="selected=null;playing=null"><X :size="17"/></button></header><div class="catalog-detail-preview" :class="{'is-transparent':selected.kind==='sticker'}"><video v-if="playing?.kind==='video'" :src="mediaUrl(playing.url)" controls autoplay playsinline :poster="mediaUrl(playing.poster_url)"/><img v-else-if="selected.poster_url||(selected.url&&['image','sticker','character'].includes(selected.kind))" :src="mediaUrl(selected.poster_url||selected.url)" alt=""/><button v-else class="catalog-audio-play" :aria-label="tr('试听 {p0}',{p0:selected.name})" @click="preview(selected)"><component :is="selected.kind==='voice'?Mic2:Music2" :size="35"/><Play :size="20"/></button></div><audio v-if="playing&&['bgm','sound','voice'].includes(playing.kind)" :key="playing.key" class="catalog-audio" :src="mediaUrl(playing.url)" controls autoplay @error="error=tr('音频读取失败，请检查素材')"/><div class="catalog-detail-copy"><span>{{label(selected.kind)}}</span><h3>{{selected.name}}</h3><p>{{detail(selected)}}</p><p v-if="selected.description">{{selected.description}}</p><dl><dt>{{tr('来源')}}</dt><dd>{{originName(selected)}}</dd><dt>{{tr('文件夹')}}</dt><dd>{{selected.origin==='system'?tr('公共资源'):folderLabel(selected.folder_id)}}</dd><dt v-if="selected.size_bytes">{{tr('文件大小')}}</dt><dd v-if="selected.size_bytes">{{(selected.size_bytes/1024/1024).toFixed(2)}} MB</dd><dt v-if="selected.duration">{{tr('时长')}}</dt><dd v-if="selected.duration">{{duration(selected.duration)}}</dd><dt v-if="selected.asset_id">{{tr('资产标识')}}</dt><dd v-if="selected.asset_id">{{selected.asset_id}}<button class="catalog-icon" :aria-label="tr('复制资产 ID')" @click="copyId(selected.asset_id)"><Copy :size="13"/></button></dd></dl><p v-if="selected.kind==='voice'">{{tr('用于角色或旁白的参考音色，与背景音乐独立管理。')}}</p></div><div class="catalog-detail-actions"><AppButton variant="primary" :disabled="!editable||(!!selected.state&&selected.state!=='ready')" @click="applyItem=selected"><Plus :size="15"/>{{selected.kind==='voice'?tr('绑定角色或旁白'):tr('用于项目')}}</AppButton><AppButton :disabled="!editable||!selected.editable" @click="renameValue=selected.name;dialog='rename'"><Pencil :size="14"/>{{tr('重命名')}}</AppButton></div></aside>
  </div>
  <ElDialog class="resource-library-dialog" :class="{'resource-library-dialog--upload':dialog==='upload'}" :model-value="!!dialog" :title="tr(dialog==='upload'?'上传资源':dialog==='move'?'移动资源':dialog==='rename'?'重命名资源':'文件夹设置')" :width="dialog==='upload'?'720px':'520px'" append-to-body @close="dialog=null">
   <template v-if="dialog==='upload'"><div class="catalog-upload">
    <div class="catalog-upload__field"><span class="catalog-upload__label">{{tr('资源类型')}}</span><AppSelect v-model="uploadKind" :options="(['video','image','bgm','sound','sticker','voice'] as const).map(value=>({value,label:label(value)}))" :disabled="uploading" :ariaLabel="tr('资源类型')" :menu-z-index="3000" /></div>
    <div class="catalog-upload__path"><span class="catalog-upload__label">{{tr('保存位置')}}</span><span class="catalog-upload__path-value"><Folder :size="14" aria-hidden="true"/>{{folderLabel(folder||0)}}</span></div>
    <CatalogVoiceUpload v-if="uploadKind==='voice'" ref="voiceForm" :folder-id="folder||0" @done="dialog=null;load()"/>
    <template v-else><div class="catalog-upload__field"><span class="catalog-upload__label">{{tr('上传文件')}}</span><AppFileDropzone :accept="accept" multiple :disabled="uploading" :title="tr('点击选择文件')" :hint="tr('也可以将文件拖拽到这里')" @select="acceptFiles"/><p class="catalog-upload__hint">{{capabilities?.kinds[uploadKind]?.formats.join(' / ')}} · {{capabilities?.kinds[uploadKind]?.max_size_mb}} MB</p></div>
    <article v-for="(job,index) in jobs" :key="index" class="catalog-upload-job"><strong>{{job.name}}</strong><span>{{label(job.kind)}} · {{folderLabel(job.folder)}}</span><progress v-if="job.state!=='failed'" :aria-label="tr('上传进度：{p0}',{p0:job.name})" :value="job.state==='processing'?undefined:job.progress" max="100"/><p>{{job.state==='done'?tr('上传成功，已存入资源库'):job.state==='failed'?job.error:job.state==='processing'?tr('正在校验文件…'):tr('上传中 {p0}%',{p0:job.progress})}}</p><AppButton v-if="job.state==='failed'" size="sm" @click="runJob(job)">{{tr('重试上传')}}</AppButton></article></template>
   </div></template>
   <form v-else-if="dialog==='folder'" class="catalog-form" @submit.prevent="saveFolder"><label>{{tr('文件夹名称')}}<input v-model="folderName" required maxlength="100"/></label><label>{{tr('上级目录')}}<AppSelect :model-value="String(folderParent)" :options="[{value:'0',label:tr('根目录')},...folders.filter(row=>row.editable!==false&&!row.parent_id&&row.id!==folderEditId).map(row=>({value:String(row.id),label:row.name}))]" :ariaLabel="tr('上级目录')" :disabled="busy" :menu-z-index="3000" @update:model-value="folderParent=Number($event)" /></label><AppButton type="submit" variant="primary" :disabled="busy">{{tr('保存')}}</AppButton></form>
   <form v-else-if="dialog==='rename'" class="catalog-form" @submit.prevent="rename"><label>{{tr('名称')}}<input v-model="renameValue" required maxlength="255"/></label><AppButton type="submit" variant="primary" :disabled="busy">{{tr('保存')}}</AppButton></form>
   <form v-else-if="dialog==='move'" class="catalog-form" @submit.prevent="move"><label>{{tr('目标文件夹')}}<AppSelect :model-value="String(moveFolder)" :options="[{value:'0',label:tr('未分类')},...orderedFolders.filter(row=>row.editable!==false).map(row=>({value:String(row.id),label:folderLabel(row.id)}))]" :ariaLabel="tr('目标文件夹')" :disabled="busy" :menu-z-index="3000" @update:model-value="moveFolder=Number($event)" /></label><AppButton type="submit" variant="primary" :disabled="busy">{{tr('移动到此处')}}</AppButton></form><p v-if="error" role="alert">{{error}}</p>
  <template #footer><div v-if="dialog==='upload'&&uploadKind==='voice'" class="catalog-upload__actions"><AppButton type="button" variant="primary" size="lg" :loading="voiceBusy" :disabled="!voiceValid" @click="submitVoice">{{tr('上传到团队资源库')}}</AppButton></div></template>
  </ElDialog><CatalogApplyDialog :item="applyItem" @close="applyItem=null"/>
 </section>
</template>
<style scoped src="./catalog.css"></style>
